use std::io::{self, Read, Write};

/// Takes ownership. The caller cannot use its String afterwards.
fn consume(s: String) -> usize {
    s.len()
}

/// Takes ownership and gives it back, changed.
fn shout(mut s: String) -> String {
    s.make_ascii_uppercase();
    s
}

/// Borrows. The caller keeps ownership and can use it again.
fn measure(s: &String) -> usize {
    s.len()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for line in input.lines() {
        let word = line.trim().to_string();
        if word.is_empty() {
            continue;
        }

        // Borrow twice: both of these leave `word` usable.
        let n = measure(&word);
        let m = measure(&word);
        writeln!(out, "measured {} {}", n, m).unwrap();

        // Move out and back: `word` is dead, `loud` owns the data now.
        let loud = shout(word);
        writeln!(out, "shout {}", loud).unwrap();

        // Move in for good. `loud` is dead after this line.
        let len = consume(loud);
        writeln!(out, "consumed {}", len).unwrap();
    }
}
